-- 457_hidden_curated_3.sql — #457 Columbus story batch part 4: 11 HIDDEN storyless OSM pins from the 131-pin gate-drops
-- union brought back with a story (drafted 2026-11-05). Same shape and rules as 457_hidden_curated.sql: exact stored name at the
-- stored coordinate, read from the stored places:v34 rows on 2026-11-05 and confirmed hidden by a live serve read of all 50
-- stored tiles; all 11 pass #542 by pin id (the containing tile stores each). Two union pins that FAIL #542 ("Modern Head",
-- "Our Single Garment of Destiny,") are seeded in names-457-columbus-4.txt under other names instead. Batch file — run in the
-- Mac session after the seed commit, after 457_hidden_curated.sql and _2.sql, then curated_category_backfill(true).
-- Expect 11 returned names, the first "Christopher Columbus Discovery Monument"; "Success. No rows returned" means the
-- guard skipped (already run — FROM RIVERSIDE (7)).
with v(name, lat, lng, description, source_url, note) as (values
  ($t$Christopher Columbus Discovery Monument$t$, 39.960711::double precision, -82.999504::double precision, $t$Alfonso Pelzer's copper statue of Christopher Columbus holding a globe, made around 1890–1892 by the W. H. Mullins Company, was donated to the state by the Pontifical College Josephinum and moved here to Capitol Square.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_Christopher_Columbus_(Ohio_Statehouse)$t$, $t$#457 hidden-pin row (part 4, union): osm_node5421655680, stored in 799_-1660; containing tile 799_-1660 stores it (#542)$t$),
  ($t$Hammer of Justice$t$, 39.959505::double precision, -83.002234::double precision, $t$Andrew F. Scott's Gavel, installed in the Ohio Judicial Center's south reflecting pool in 2008, was considered the largest gavel in the world when finished, and at $200,000 it is the costliest of the center's roughly 170 works of art.$t$, $t$https://en.wikipedia.org/wiki/Gavel_(sculpture)$t$, $t$#457 hidden-pin row (part 4, union): osm_node3659290265, stored in 799_-1660; containing tile 799_-1660 stores it (#542)$t$),
  ($t$Lincoln Goodale$t$, 39.974541::double precision, -83.005505::double precision, $t$John Quincy Adams Ward sculpted this 1888 bronze bust of Dr. Lincoln Goodale, the area's first physician, on a granite base designed by Richard Morris Hunt.$t$, $t$https://en.wikipedia.org/wiki/Lincoln_Goodale_Monument$t$, $t$#457 hidden-pin row (part 4, union): osm_node6031512652, stored in 799_-1660; containing tile 799_-1660 stores it (#542)$t$),
  ($t$These Are My Jewels$t$, 39.961793::double precision, -82.999751::double precision, $t$Levi Scofield's bronze group of seven Ohio Civil War leaders with Cornelia, the Roman mother who called her sons her jewels, was made for the 1893 Chicago world's fair and moved to Columbus when the fair ended.$t$, $t$https://en.wikipedia.org/wiki/These_Are_My_Jewels$t$, $t$#457 hidden-pin row (part 4, union): osm_node5421655685, stored in 799_-1660; containing tile 799_-1660 stores it (#542)$t$),
  ($t$Nicklaus Museum$t$, 40.009887::double precision, -83.023626::double precision, $t$Honouring Jack Nicklaus, who grew up in Upper Arlington and played golf for Ohio State in the 1960s, this museum had its grand opening on May 21, 2002, and was transferred to Ohio State in 2005.$t$, $t$https://en.wikipedia.org/wiki/Jack_Nicklaus_Museum$t$, $t$#457 hidden-pin row (part 4, union): osm_way503889161, stored in 800_-1660, 800_-1661; containing tile 800_-1660 stores it (#542)$t$),
  ($t$CCAD's ART Sign$t$, 39.965356::double precision, -82.99009::double precision, $t$Doris Shlayn's red steel sculpture spelling ART, installed outside the Columbus College of Art and Design in 2001, weighs 31 tons, and its A straddles East Gay Street so cars and pedestrians pass underneath.$t$, $t$https://en.wikipedia.org/wiki/ART_(sculpture)$t$, $t$#457 hidden-pin row (part 4, union): osm_node2970772394, stored in 799_-1659, 799_-1660, 800_-1660; containing tile 799_-1660 stores it (#542)$t$),
  ($t$Near East Side Historic District$t$, 39.962564::double precision, -82.966571::double precision, $t$Listed on the National Register in 1978, this district takes in Franklin Park and its conservatory, the former Engine House No. 12 and the Joseph Warren Yost House at 1216 Bryden Road.$t$, $t$https://en.wikipedia.org/wiki/Columbus_Near_East_Side_District$t$, $t$#457 hidden-pin row (part 4, union): osm_node357472747, stored in 799_-1659, 799_-1660; containing tile 799_-1659 stores it (#542)$t$),
  ($t$Brewery District$t$, 39.950288::double precision, -83.000145::double precision, $t$Louis Hoster, Jacob Silbernagel and George M. Herancourt opened the first brewery here in 1836, where the Scioto River, the Columbus Feeder canal and a spring-fed ravine met; the Schlee, Born's Capitol and Gambrinus breweries followed.$t$, $t$https://en.wikipedia.org/wiki/Brewery_District$t$, $t$#457 hidden-pin row (part 4, union): osm_node357472786, stored in 799_-1660; containing tile 799_-1660 stores it (#542)$t$),
  ($t$Orton Geological Museum$t$, 39.998208::double precision, -83.01192::double precision, $t$Named for Edward Orton Sr., Ohio State's first president and Ohio's State Geologist, Orton Hall opened in 1893 and holds this museum, where a 24-foot replica of Cryolophosaurus ellioti, a dinosaur found in Antarctica, has stood in the lobby since 2018.$t$, $t$https://en.wikipedia.org/wiki/University,_Hayes_and_Orton_Halls$t$, $t$#457 hidden-pin row (part 4, union): osm_node618411600, stored in 800_-1660, 800_-1661; containing tile 800_-1660 stores it (#542)$t$),
  ($t$Leatherlips Monument$t$, 40.117007::double precision, -83.110558::double precision, $t$Ralph Helmick designed this eleven-foot limestone portrait of the Wyandot chief Leatherlips, dedicated on July 1, 1990, as the Dublin Arts Council's first outdoor public sculpture.$t$, $t$https://www.hmdb.org/m.asp?m=115842$t$, $t$#457 hidden-pin row (part 4, union): osm_node2308554368, stored in 802_-1662, 802_-1663, 803_-1662; containing tile 802_-1662 stores it (#542)$t$),
  ($t$Bill Moose Memorial$t$, 40.047336::double precision, -83.094612::double precision, $t$This structure of Scioto River boulders marks the grave of Bill Moose, who died in 1937 and is considered the last Wyandot in Ohio, the federal government having expelled the tribe's members from the state in 1843.$t$, $t$https://uahistory.org/porchpartytrivia$t$, $t$#457 hidden-pin row (part 4, union): osm_node357517057, stored in 801_-1661, 801_-1662; containing tile 801_-1662 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
